// Filter for updates from yesterday
const yesterday = new Date();
yesterday.setDate(yesterday.getDate() - 1);
const yesterdayStr = yesterday.toISOString().split('T')[0];

const filteredRows = $input.all().filter(item => {
  const dateStr = item.json.date || item.json.Date;
  return dateStr && dateStr.startsWith(yesterdayStr);
});

if (filteredRows.length === 0) {
  return [{ json: { message: 'No updates found for yesterday' } }];
}

// Format the updates for AI processing
let updatesText = 'Team updates for ' + yesterdayStr + ':
';
for (const item of filteredRows) {
  const row = item.json;
  const name = row.name || row.Name || 'Anonymous';
  const update = row.update || row.Update || 'No update provided';
  updatesText += '
' + name + ': ' + update;
}

return [{ json: { updates: updatesText } }];

