// Parse the AI response and format for Slack
try {
  const aiResponse = $input.first().json.message.content;
  const parsed = JSON.parse(aiResponse);

  let slackMessage = ':calendar: *Daily Standup Digest* for ' + new Date(Date.now() - 86400000).toLocaleDateString() + '\n\n';

  if (parsed.blockers && parsed.blockers.length > 0) {
    slackMessage += '*:blocker: BLOCKERS:*\n';
    for (const blocker of parsed.blockers) {
      slackMessage += `- ${blocker}\n`;
    }
    slackMessage += '\n';
  } else {
    slackMessage += '*:white_check_mark: No blockers reported*\n\n';
  }

  if (parsed.progress && parsed.progress.length > 0) {
    slackMessage += '*:rocket: PROGRESS:*\n';
    for (const progress of parsed.progress) {
      slackMessage += `- ${progress}\n`;
    }
  }

  return [{ json: { text: slackMessage } }];
} catch (error) {
  return [{ json: { text: 'Error parsing AI response: ' + error.message } }];
}
